), up AS (
INSERT INTO ref_hyperlanes (a, b, route_name, lane_class, length_px, edition, source_url, source_revision)
SELECT e.a, e.b, r.route_name, e.lane_class, e.length_px, r.edition, r.source_url, r.source_revision FROM e JOIN r ON r.i = e.i
ON CONFLICT (a, b, route_name) DO UPDATE SET lane_class = EXCLUDED.lane_class, length_px = EXCLUDED.length_px, edition = EXCLUDED.edition, source_url = EXCLUDED.source_url, source_revision = EXCLUDED.source_revision RETURNING 1
)
DELETE FROM ref_hyperlanes h WHERE NOT EXISTS (SELECT 1 FROM e JOIN r ON r.i = e.i WHERE e.a = h.a AND e.b = h.b AND r.route_name = h.route_name);

UPDATE ref_systems s SET on_lane = EXISTS (SELECT 1 FROM ref_hyperlanes h WHERE h.a = s.id OR h.b = s.id);

INSERT INTO ref_nav_hazards (system_id, upgrades, note) VALUES
('kessel-t-10',2,'Kessel: Maw, black holes')
ON CONFLICT (system_id, note) DO UPDATE SET upgrades = EXCLUDED.upgrades;
